JOBS = [["index.html", [[".howto{border:0;", ".ov.fx{position:fixed;z-index:40}\n.nickin{width:100%;box-sizing:border-box;border:2px solid var(--edge);border-radius:14px;padding:12px 14px;font:800 18px var(--fd,system-ui);color:var(--ink);text-align:center;background:var(--panel-2);outline:none}\n.nickin:focus{border-color:#9b5cf0}\n.nerr{min-height:18px;font-size:13px;font-weight:800;color:var(--danger)}\n.menurow{display:flex;gap:8px;flex-wrap:wrap;align-items:center}\n.me{display:inline-flex;align-items:center;gap:6px;border:0;background:rgba(255,255,255,.55);color:var(--ink);font-weight:800;font-size:14px;padding:9px 14px;border-radius:999px;box-shadow:0 2px 0 var(--edge)}\n.tmr{font-weight:900;font-size:13px;color:var(--muted);font-variant-numeric:tabular-nums}\n.wtime{font-weight:800;font-size:14px;color:var(--muted);line-height:1.4}\n.prize{font-size:13px;font-weight:900;color:#4a2c00;background:linear-gradient(180deg,#ffe36b,#ffd02b);padding:5px 12px;border-radius:999px;box-shadow:0 2px 0 #eb9b00}\n.rk{width:100%;display:flex;flex-direction:column;gap:4px;max-height:46vh;overflow-y:auto}\n.rkr{display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:12px;background:var(--panel-2);font-weight:800;font-size:14px;color:var(--ink);text-align:left}\n.rkr.me{background:#fff3c4;box-shadow:inset 0 0 0 2px #ffd02b}\n.rkr .n{width:28px;font-weight:900;color:var(--muted);font-variant-numeric:tabular-nums}\n.rkr .nm{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.rkr .v{font-variant-numeric:tabular-nums;font-weight:900}\n.lvsel{display:flex;align-items:center;gap:8px;justify-content:center;font-weight:900;color:var(--ink)}\n.lvsel button{border:0;background:var(--panel-2);border-radius:10px;width:36px;height:36px;font:900 18px system-ui;color:var(--ink);box-shadow:0 2px 0 var(--edge)}\n.howto{border:0;", 1], ["<button class=\"howto\" id=\"howBtn\">Как играть, за 30 секунд</button>", "<div class=\"menurow\"><button class=\"howto\" id=\"howBtn\">Как играть, за 30 секунд</button><button class=\"howto\" id=\"rankBtn\">🏆 Рейтинги</button><button class=\"me\" id=\"meBtn\">Выбрать ник</button></div>", 1], ["  <!-- ============ GAME ============ -->", "  <div class=\"ov fx\" id=\"ovNick\" hidden><div class=\"card\">\n    <div class=\"eyebrow\">Добро пожаловать</div>\n    <h2>Как тебя звать?</h2>\n    <p>Ник будет в рейтингах. От 3 до 16 символов: буквы, цифры, пробел, точка, дефис.</p>\n    <input class=\"nickin\" id=\"nickIn\" maxlength=\"16\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\" placeholder=\"Твой ник\">\n    <div class=\"nerr\" id=\"nickErr\"></div>\n    <div class=\"row\"><button class=\"btn primary\" id=\"nickOk\">Играть</button></div>\n  </div></div>\n\n  <div class=\"ov fx\" id=\"ovRank\" hidden><div class=\"card\">\n    <div class=\"eyebrow\">Рейтинги</div>\n    <div class=\"tabs\" role=\"tablist\" style=\"width:100%\">\n      <button class=\"tab\" role=\"tab\" id=\"rkTabS\" aria-selected=\"true\">Звезды</button>\n      <button class=\"tab\" role=\"tab\" id=\"rkTabT\" aria-selected=\"false\">Время смены</button>\n    </div>\n    <div class=\"lvsel\" id=\"rkLv\" hidden><button id=\"rkPrev\" aria-label=\"Предыдущая смена\">‹</button><span id=\"rkLvT\">Смена 1</span><button id=\"rkNext\" aria-label=\"Следующая смена\">›</button></div>\n    <div class=\"rk\" id=\"rkList\"></div>\n    <p id=\"rkMe\" style=\"font-size:14px\"></p>\n    <div class=\"row\"><button class=\"btn ghost\" id=\"rkNick\">Сменить ник</button><button class=\"btn primary\" id=\"rkClose\">Закрыть</button></div>\n  </div></div>\n\n  <!-- ============ GAME ============ -->", 1], ["<span class=\"badge\" id=\"gBadge\" hidden>Сложно</span></div>", "<span class=\"badge\" id=\"gBadge\" hidden>Сложно</span><span class=\"tmr\" id=\"gTime\">0:00</span></div>", 1], ["  S.t+=dt;\n", "  S.t+=dt;\n  if(S.state==='play'){S.tPlay=S.t;const ts=Math.floor(S.t);if(ts!==S.tShown){S.tShown=ts;const e=document.getElementById('gTime');if(e)e.textContent=fmtT(ts)}}\n", 1], ["<div class=\"stars\" id=\"winStars\"></div>", "<div class=\"stars\" id=\"winStars\"></div>\n      <div class=\"wtime\" id=\"winTime\"></div>\n      <span class=\"prize\" id=\"winPrize\" hidden></span>", 1], ["/* ================= game state ================= */", "/* ================= nick, records, ratings ================= */\nfunction rpc(name,body){return fetch(AN.url+'/rest/v1/rpc/'+name,{method:'POST',headers:{apikey:AN.key,...(AN.key.startsWith('ey')?{Authorization:'Bearer '+AN.key}:{}),'Content-Type':'application/json'},body:JSON.stringify(body||{})}).then(r=>r.ok?r.json():r.json().then(e=>Promise.reject(e&&e.message||r.status)))}\nfunction fmtT(s){s=Math.max(0,Math.round(s||0));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}\nfunction escH(t){return String(t).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'})[c])}\nfunction nickOk(n){return /^[A-Za-zА-Яа-яЁё0-9_ .-]{3,16}$/.test(n)}\nfunction syncNick(){if(!SV.nick||!SV.nickPending||!AN.url.startsWith('http'))return;rpc('set_nick',{p_pid:PID,p_nick:SV.nick}).then(r=>{if(r&&r.ok){SV.nickPending=false;save();renderMe()}}).catch(()=>{})}\nfunction renderMe(){const b=$('#meBtn');if(b)b.textContent=SV.nick?'Игрок: '+SV.nick:'Выбрать ник'}\nfunction askNick(after){$('#ovNick').hidden=false;const inp=$('#nickIn');inp.value=SV.nick||'';$('#nickErr').textContent='';setTimeout(()=>inp.focus(),60);\n  $('#nickOk').onclick=()=>{ac();const n=inp.value.trim().replace(/\\s+/g,' ');\n    if(!nickOk(n)){$('#nickErr').textContent='От 3 до 16 символов: буквы, цифры, пробел, точка, дефис';return}\n    $('#nickOk').disabled=true;$('#nickErr').textContent='Проверяю ник...';\n    const done=ok=>{$('#nickOk').disabled=false;if(!ok)return;SV.nick=n;save();renderMe();track('nick_set',{});$('#ovNick').hidden=true;if(after)after()};\n    if(!AN.url.startsWith('http')){SV.nickPending=true;done(true);return}\n    rpc('set_nick',{p_pid:PID,p_nick:n}).then(r=>{\n      if(r&&r.ok){SV.nickPending=false;done(true)}\n      else if(r&&r.err==='taken'){$('#nickErr').textContent='Этот ник уже занят, придумай другой';done(false)}\n      else{$('#nickErr').textContent='Такой ник не подходит';done(false)}\n    }).catch(()=>{SV.nickPending=true;done(true)});\n  };\n  inp.onkeydown=e=>{if(e.key==='Enter')$('#nickOk').click()};\n}\nlet RK={tab:'s',lvl:1};\nfunction rankRow(i,nm,v,me){return '<div class=\"rkr'+(me?' me':'')+'\"><span class=\"n\">'+i+'</span><span class=\"nm\">'+escH(nm)+(me?' (ты)':'')+'</span><span class=\"v\">'+v+'</span></div>'}\nfunction loadRank(){const L=$('#rkList');L.innerHTML='<p>Загружаю...</p>';$('#rkMe').textContent='';\n  $('#rkLv').hidden=RK.tab!=='t';$('#rkLvT').textContent='Смена '+RK.lvl;\n  rpc('leaderboard',{p_lvl:RK.lvl,p_pid:PID}).then(d=>{\n    if(RK.tab==='s'){const a=d.stars_top||[];L.innerHTML=a.length?a.map(r=>rankRow(r.rank,r.nick,'★ '+r.stars,r.me)).join(''):'<p>Пока никого. Пройди смену и стань первым</p>';\n      const m=d.stars_me;$('#rkMe').textContent=m?('Твое место: '+m.rank+' из '+m.of+' · ★ '+m.stars+' · смен пройдено: '+m.lvls):'Пройди смену, чтобы попасть в рейтинг'}\n    else{const a=d.time_top||[];L.innerHTML=a.length?a.map(r=>rankRow(r.rank,r.nick,fmtT(r.secs),r.me)).join(''):'<p>Эту смену еще никто не прошел. Будь первым</p>';\n      const m=d.time_me;$('#rkMe').textContent=m?('Твое место: '+m.rank+' из '+m.of+' · лучшее время '+fmtT(m.secs)):'Пройди эту смену, чтобы попасть в рейтинг'}\n  }).catch(()=>{L.innerHTML='<p>Нет связи с рейтингом. Проверь интернет</p>'})}\nfunction showRank(tab,lvl){RK.tab=tab||RK.tab;RK.lvl=Math.max(1,lvl||RK.lvl||1);$('#rkTabS').setAttribute('aria-selected',RK.tab==='s');$('#rkTabT').setAttribute('aria-selected',RK.tab==='t');$('#ovRank').hidden=false;loadRank();track('rank_open',{tab:RK.tab,lvl:RK.lvl})}\n$('#rkTabS').onclick=()=>showRank('s');\n$('#rkTabT').onclick=()=>showRank('t');\n$('#rkPrev').onclick=()=>{if(RK.lvl>1){RK.lvl--;loadRank()}};\n$('#rkNext').onclick=()=>{RK.lvl++;loadRank()};\n$('#rkClose').onclick=()=>{$('#ovRank').hidden=true};\n$('#rkNick').onclick=()=>{$('#ovRank').hidden=true;askNick(()=>showRank())};\n$('#meBtn').onclick=()=>{ac();askNick()};\n$('#rankBtn').onclick=()=>{ac();showRank('s',Math.max(1,SV.unl-1))};\nfunction fetchRecord(n){if(!AN.url.startsWith('http')||!S)return;S.lbRec=undefined;rpc('leaderboard',{p_lvl:n,p_pid:PID}).then(d=>{if(S&&S.n===n)S.lbRec=d.record==null?null:d.record}).catch(()=>{})}\n\n/* ================= game state ================= */", 1], ["  track('level_start',{lvl:n,tries:SV.tries[n],unl:SV.unl});", "  track('level_start',{lvl:n,tries:SV.tries[n],unl:SV.unl});\n  S.tShown=-1;fetchRecord(n);", 1], ["  if(S.spec.boss){SV.inv.hint++;SV.inv.hammer++}\n  SV.coins+=coins;", "  if(S.spec.boss){SV.inv.hint++;SV.inv.hammer++}\n  const secs=Math.max(1,Math.floor(S.tPlay||S.t));SV.best=SV.best||{};const pb=SV.best[S.n];let prize=0,prizeTxt='';\n  if(!S.cont&&SV.nick&&typeof S.lbRec==='number'&&secs<S.lbRec){prize=100;prizeTxt='Рекорд смены! Ты быстрее всех: +100'}\n  else if(!S.cont&&SV.nick&&S.lbRec===null){prize=30;prizeTxt='Ты первый прошел эту смену: +30'}\n  else if(pb&&secs<pb){prize=15;prizeTxt='Личный рекорд: +15'}\n  if(!pb||secs<pb)SV.best[S.n]=secs;\n  coins+=prize;\n  SV.coins+=coins;", 1], ["track('level_win',{lvl:S.n,stars:st,secs:Math.round(S.t),", "track('level_win',{lvl:S.n,stars:st,secs,prize,", 1], ["    $('#winCoins').textContent='+'+coins;\n", "    $('#winCoins').textContent='+'+coins;\n    $('#winPrize').hidden=!prize;$('#winPrize').textContent=prizeTxt;\n    const wn=S.n;$('#winTime').textContent='Время '+fmtT(secs)+(pb?' · лучшее было '+fmtT(pb):'');\n    if(SV.nick&&AN.url.startsWith('http')&&!S.cont)setTimeout(()=>rpc('leaderboard',{p_lvl:wn,p_pid:PID}).then(d=>{const m=d.time_me;if(m&&S&&S.n===wn&&!$('#ovWin').hidden)$('#winTime').textContent='Время '+fmtT(secs)+' · место '+m.rank+' из '+m.of+' в рейтинге смены'}).catch(()=>{}),1500);\n    else if(!SV.nick)$('#winTime').textContent+=' · выбери ник, чтобы попасть в рейтинг';\n", 1], ["      <div class=\"step\"><div class=\"sn\">!</div><div><b>Секрет:</b>", "      <div class=\"step\"><div class=\"sn\">5</div><div><b>Лихорадка.</b> Над картиной есть шкала «ЛИХОРАДКА». Каждый сбитый кубик ее наполняет, а если долго не стрелять, она сдувается. Заполнил: 6 секунд конвейер едет в 1,6 раза быстрее, и каждый сбитый кубик дает монеты. Запускай стрелков пачкой без пауз, чтобы ее поймать.</div></div>\n      <div class=\"step\"><div class=\"sn\">6</div><div><b>Время и рейтинги.</b> Время смены идет сверху. Проходи быстрее и собирай звезды: в «Рейтингах» видно, кто лучший. Побил свое время: +15 монет. Побил рекорд смены среди всех игроков: +100. Прошел смену первым: +30. Рекорды считаются без продолжений после проигрыша.</div></div>\n      <div class=\"step\"><div class=\"sn\">!</div><div><b>Секрет:</b>", 1], ["track('app_open',{unl:SV.unl,day:DAY,stars:Object.values(SV.stars).reduce((a,b)=>a+b,0)});", "track('app_open',{unl:SV.unl,day:DAY,stars:Object.values(SV.stars).reduce((a,b)=>a+b,0),nick:!!SV.nick});\nrenderMe();syncNick();\nif(!SV.nick)setTimeout(()=>{if($('#ovHelp').hidden&&$('#game').hidden)askNick()},400);", 1]]], ["skin/stats.html", [["  <section class=\"card help\">", "  <section class=\"card\">\n    <h2>Игроки по никам</h2>\n    <p class=\"lead\">Нажми на ник, чтобы увидеть его смены: время, звезды, победы и поражения.</p>\n    <div class=\"scroll\"><table id=\"ptbl\"></table></div>\n    <div id=\"pdet\" style=\"margin-top:12px\"></div>\n  </section>\n  <section class=\"card help\">", 1], ["function tile(k,v,h){", "function esc(t){return String(t==null?'':t).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'})[c])}\nfunction mmss(s){if(s==null)return '';s=+s;return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}\nfunction rpcS(n,b){return fetch(AN.url+'/rest/v1/rpc/'+n,{method:'POST',headers:{apikey:AN.key,Authorization:'Bearer '+AN.key,'Content-Type':'application/json'},body:JSON.stringify(b||{})}).then(r=>r.ok?r.json():Promise.reject(r.status))}\nconst PLN={web:'Браузер',pwa:'Иконка PWA',apk:'APK',android:'Android',ios:'iPhone'};\nasync function loadPlayers(){\n  const T=$('#ptbl');if(!AN.url.startsWith('http')){T.innerHTML='';return}\n  try{const a=await rpcS('players_stats');\n    if(!a.length){T.innerHTML='<tr><td class=\"l muted\">Пока никто не выбрал ник</td></tr>';return}\n    let h='<tr><th class=\"l\">Ник</th><th>Звезды</th><th>Побед</th><th>Поражений</th><th>Дошел до</th><th>Сессий</th><th class=\"l\">Откуда</th><th class=\"l\">Был</th></tr>';\n    for(const p of a)h+='<tr class=\"pr\" data-n=\"'+esc(p.nick)+'\" style=\"cursor:pointer\"><td class=\"l\"><b style=\"color:var(--accent)\">'+esc(p.nick)+'</b></td><td>'+p.stars+'</td><td>'+p.wins+'</td><td>'+p.losses+'</td><td>'+(p.max_lvl||'')+'</td><td>'+p.sessions+'</td><td class=\"l\">'+esc(PLN[p.plat]||p.plat||'')+'</td><td class=\"l\">'+new Date(p.last_seen).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+'</td></tr>';\n    T.innerHTML=h;T.querySelectorAll('tr.pr').forEach(r=>r.onclick=()=>loadDetail(r.dataset.n));\n  }catch(e){T.innerHTML='<tr><td class=\"l muted\">Не удалось загрузить игроков</td></tr>'}\n}\nasync function loadDetail(n){const D=$('#pdet');D.innerHTML='<div class=\"muted\">Загрузка...</div>';\n  try{const a=await rpcS('player_detail',{p_nick:n});\n    let h='<h2 style=\"font-size:16px;margin:4px 0 8px\">'+esc(n)+': смены</h2><div class=\"scroll\"><table><tr><th>Смена</th><th>Попыток</th><th>Побед</th><th>Поражений</th><th>Лучшее время</th><th>Звезды</th><th>Бустеры</th><th>Продолжения</th></tr>';\n    for(const x of a)h+='<tr><td><b>'+x.lvl+'</b></td><td>'+x.starts+'</td><td>'+x.wins+'</td><td>'+x.losses+'</td><td>'+mmss(x.best_secs)+'</td><td>'+(x.stars==null?'':'★'.repeat(x.stars))+'</td><td>'+x.boosters+'</td><td>'+x.continues+'</td></tr>';\n    D.innerHTML=h+'</table></div>';D.scrollIntoView({behavior:'smooth',block:'nearest'});\n  }catch(e){D.innerHTML='<div class=\"muted\">Не удалось загрузить</div>'}\n}\nfunction tile(k,v,h){", 1], ["  render(d);\n}", "  render(d);\n  loadPlayers();\n}", 1], ["({web:'Браузер',pwa:'Иконка на экране (PWA)',apk:'Android-приложение'})", "({web:'Браузер',pwa:'Иконка на экране (PWA)',apk:'Android APK с сайта',android:'Приложение Android',ios:'Приложение iPhone'})", 1]]]]
for path, pairs in JOBS:
    s = open(path, encoding='utf-8').read()
    for old, new, cnt in pairs:
        assert s.count(old) == cnt, (path, old[:80])
        s = s.replace(old, new)
    open(path, 'w', encoding='utf-8').write(s)
print('v5 applied')
